import express from 'express';
import pg from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20
});

// Middleware: extract tenant from JWT (set by upstream proxy)
app.use((req, res, next) => {
  req.tenantId = req.headers['x-tenant-id'];
  req.userId = req.headers['x-user-id'];
  next();
});

// VULNERABLE: SQL injection in order search
app.get('/api/orders/search', async (req, res) => {
  const { status, date_from, date_to, sort_by } = req.query;

  let query = `SELECT o.id, o.amount, o.status, o.created_at, c.email 
               FROM orders o JOIN customers c ON o.customer_id = c.id 
               WHERE o.tenant_id = '${req.tenantId}'`;

  if (status) {
    query += ` AND o.status = '${status}'`;
  }
  if (date_from) {
    query += ` AND o.created_at >= '${date_from}'`;
  }
  if (date_to) {
    query += ` AND o.created_at <= '${date_to}'`;
  }

  // sort_by allows column name injection
  if (sort_by) {
    query += ` ORDER BY ${sort_by}`;
  } else {
    query += ` ORDER BY o.created_at DESC`;
  }

  query += ` LIMIT 100`;

  try {
    const result = await pool.query(query);
    res.json({ orders: result.rows });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Also vulnerable: direct string interpolation
app.get('/api/orders/:id', async (req, res) => {
  const query = `SELECT o.*, c.email, c.phone FROM orders o 
                 JOIN customers c ON o.customer_id = c.id 
                 WHERE o.id = '${req.params.id}' AND o.tenant_id = '${req.tenantId}'`;
  try {
    const result = await pool.query(query);
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Export endpoint - also injectable via filename param
app.get('/api/orders/export/:format', async (req, res) => {
  const { filter } = req.query;
  let query = `SELECT o.id, o.amount, o.status FROM orders o WHERE o.tenant_id = '${req.tenantId}'`;
  if (filter) {
    query += ` AND ${filter}`;
  }
  try {
    const result = await pool.query(query);
    res.setHeader('Content-Disposition', `attachment; filename=export.${req.params.format}`);
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

app.listen(3000, () => console.log('Order service running on :3000'));
